import subprocess
EXE="/workspace/executable"
def run(args, input_text=None, cwd="/tmp"):
    r = subprocess.run([EXE]+args, input=input_text.encode() if input_text is not None else None, capture_output=True, cwd=cwd)
    return r.stdout.decode(), r.stderr.decode(), r.returncode

