# ---------- Formatting helpers ----------
def find_comment_index(line):
    # return index of % starting comment, or -1
    for i,ch in enumerate(line):
        if ch == "%":
            if i == 0 or line[i-1] != "\\":
                return i
    return -1

def split_code_comment(line):
    idx = find_comment_index(line)
    if idx == -1:
        return line, ""
    else:
        return line[:idx], line[idx:]

def is_skip_line(line):
    # line already rstrip trailing
    return line.endswith("% tex-fmt: skip")

def is_off_line(line):
    return line.endswith("% tex-fmt: off")

def is_on_line(line):
    return line.endswith("% tex-fmt: on")

def has_valid_verb(line):
    # check for \verb without star, with delimiters
    # Find \verb not followed by letter? Actually \verb must be exactly, then delimiter
    # \verb* should not count
    i = 0
    while True:
        idx = line.find("\\verb", i)
        if idx == -1:
            return False
        after = idx + 5
        # check if at end or next char is *? If *, then it's \verb*, skip (not valid)
        if after < len(line) and line[after] == "*":
